/bin/bash -lc "python - <<'PY'
import json
p='run_trace/galaxy_tool_run_002/validation_response.json'
x=json.load(open(p))
def walk(v, depth=0):
    if isinstance(v, dict):
        mc=v.get('model_class')
        if mc in {'Conditional','ConditionalWhen','SelectToolParameter','BooleanToolParameter','DataToolParameter','TextToolParameter'}:
            print('  '*depth, mc, 'name=',v.get('name'),'value=',v.get('value'),'test_param=',(v.get('test_param') or {}).get('name'))
        for k in ('inputs','cases'):
            if k in v: walk(v[k],depth+1)
        if 'test_param' in v: walk(v['test_param'],depth+1)
    elif isinstance(v,list):
        for y in v: walk(y,depth)
walk(x.get('inputs',[]))
PY"
